document.function:

{def parentId, def field_value_history, def field ->
	def value = stringifyValue(field)
	def lastValue = field_value_history.options[field.importId]
	addToHistory(parentId, "changed field " + wrapElement(field.name as String, "b") + " value [" + lastValue + "] -> [" + value + "]", false)
}


{def parent_id, def text, boolean appendLine ->
	def loggedUser = userService.getLoggedOrSystem()
	def nowTime = java.time.LocalDateTime.now()
	def nowTimeFormated = nowTime.format("dd.MM.yyyy HH:mm:ss")
	def newText
	if (!appendLine) {
		newText = "\r[" + nowTimeFormated + "] " + wrapElement(loggedUser.fullName, "b") + ": " + text
	} else {
		newText = " " + text
	}
	def parentCase = findCase({it._id.eq(parent_id)})
	parentCase.dataSet["history"].value += newText
	workflowService.save(parentCase)
}


{ Double number, int scale ->
return (BigDecimal.valueOf(number).scale() > scale)
}


{ changedField ->
	log.info("changedField: ${changedField.toString()}")
	log.info("changedField.value: ${changedField.value}")
    if (changedField.value == null) {
        return
    }
	def typ_polozky = useCase.getField("typ_polozky")
    def pocet = useCase.getField("pocet")
    def sadzba_dph = useCase.getField("sadzba_dph")
    def jedn_cena_eur = useCase.getField("jedn_cena_eur")
    def jedn_cena_dph = useCase.getField("jedn_cena_dph")
    def celkom_cena_eur = useCase.getField("celkom_cena_eur")
    def celkom_cena_dph = useCase.getField("celkom_cena_dph")
	log.info("Loaded values:\ntyp_polozky = ${typ_polozky.value}\npocet = ${pocet.value}\nsadzba_dph = ${sadzba_dph.value}\njedn_cena_eur = ${jedn_cena_eur.value}\njedn_cena_dph = ${jedn_cena_dph.value}\ncelkom_cena_eur = ${celkom_cena_eur.value}\ncelkom_cena_dph = ${celkom_cena_dph.value}")
	if (changedField != sadzba_dph) {
        log.info("rounding changedField value")
		roundFieldToTwoDecimal(changedField)
    }
	if (changedField == jedn_cena_eur) {
		def nova_jedn_cena_dph = jedn_cena_eur.value * (1 + sadzba_dph.value / 100)
		def nova_celkom_cena_eur = jedn_cena_eur.value * pocet.value
		def nova_celkom_cena_dph = nova_jedn_cena_dph.value * pocet.value
		log.info("${nova_jedn_cena_dph}, ${nova_celkom_cena_eur}, ${nova_celkom_cena_dph}")
		change jedn_cena_dph value { nova_jedn_cena_dph }
		change celkom_cena_eur value { nova_celkom_cena_eur }
		change celkom_cena_dph value { nova_celkom_cena_dph }
    } else if (changedField == sadzba_dph) {
		return
    }
}


{ number -> 
if (number != null) {
        def pattern = "#.##"
        def df = new java.text.DecimalFormat(pattern)
        df.setRoundingMode(java.math.RoundingMode.HALF_UP)
        return Double.parseDouble(df.format(number).replace(",", "."))
    }
    return number
}


{ String pattern = "#.##", Double number ->
if (number) {
def df = new java.text.DecimalFormat(pattern)
df.setRoundingMode(java.math.RoundingMode.HALF_UP)
return Double.parseDouble(df.format(number).replace(",", "."))
}
return number
}


{ field ->
	if (hasScaleBiggerThan(field.value, 2)) {
		change field value { roundDouble("#.##", field.value) }
		return
	}
}


{ parentId ->
    def fpuCase = findCaseElastic(parentId)
    def items = findCasesElastic("processIdentifier:\"polozka\" AND dataSet.parent_id.textValue.keyword:\"$parentId\"", org.springframework.data.domain.PageRequest.of(0,100))
    def itemsPriceWithTariff = items.collect { it.getFieldValue("celkom_cena_dph") ?: 0 }.sum()
    setData("t6", fpuCase, [
            "polozky_suma": ["type": "number", "value": roundDouble(itemsPriceWithTariff)],
    ])
}

